     1→# ================================================================
     2→# FreeLang Bootstrap Interpreter v2 (Complete Implementation)
     3→# TypeScript evaluator.ts → FreeLang 완전 포팅
     4→#
     5→# 철학: "기록이 증명이다" - 모든 평가 로직을 FreeLang으로 구현
     6→# ================================================================
     7→
     8→# ================================================================
     9→# Part 1: 환경(Environment) 관리
    10→# ================================================================
    11→
    12→# 전역 변수 저장소 (간단한 맵 구현)
    13→let globalVars: map = {}
    14→let globalFuncs: map = {}
    15→let globalStructs: map = {}  # struct 정의 저장소
    16→
    17→# 환경 생성
    18→fn createEnv(): map {
    19→  return {
    20→    "variables": {},
    21→    "functions": globalFuncs,
    22→    "parent": null
    23→  }
    24→}
    25→
    26→# 변수 조회
    27→fn getVariable(name: string, env: map): any {
    28→  let vars = env["variables"]
    29→  
    30→  if vars[name] != null {
    31→    return vars[name]
    32→  }
    33→  
    34→  let parent = env["parent"]
    35→  if parent != null {
    36→    return getVariable(name, parent)
    37→  }
    38→  
    39→  return null
    40→}
    41→
    42→# 변수 설정
    43→fn setVariable(name: string, value: any, env: map): any {
    44→  let vars = env["variables"]
    45→  vars[name] = value
    46→  return value
    47→}
    48→
    49→# 함수 정의
    50→fn defineFunction(name: string, params: [string], body: map, env: map): any {
    51→  let funcs = env["functions"]
    52→  funcs[name] = {
    53→    "params": params,
    54→    "body": body
    55→  }
    56→  return null
    57→}
    58→
    59→# Struct 정의
    60→fn defineStruct(name: string, fields: [any], env: map): any {
    61→  globalStructs[name] = {
    62→    "fields": fields
    63→  }
    64→  return null
    65→}
    66→
    67→# Struct 타입 확인
    68→fn getStructDef(name: string): any {
    69→  return globalStructs[name]
    70→}
    71→
    72→# ================================================================
    73→# Part 2: 연산자 구현
    74→# ================================================================
    75→
    76→# 이진 연산자
    77→fn evalBinaryOp(left: any, right: any, op: string): any {
    78→  if op == "+" {
    79→    # 문자열 또는 숫자 덧셈
    80→    if left is string or right is string {
    81→      return toString(left) + toString(right)
    82→    } else {
    83→      return left + right
    84→    }
    85→  } else if op == "-" {
    86→    return left - right
    87→  } else if op == "*" {
    88→    return left * right
    89→  } else if op == "/" {
    90→    return left / right
    91→  } else if op == "%" {
    92→    return left % right
    93→  } else if op == "==" {
    94→    return left == right
    95→  } else if op == "!=" {
    96→    return left != right
    97→  } else if op == "<" {
    98→    return left < right
    99→  } else if op == ">" {
   100→    return left > right
   101→  } else if op == "<=" {
   102→    return left <= right
   103→  } else if op == ">=" {
   104→    return left >= right
   105→  } else if op == "&&" or op == "and" {
   106→    return left and right
   107→  } else if op == "||" or op == "or" {
   108→    return left or right
   109→  } else {
   110→    return null
   111→  }
   112→}
   113→
   114→# 단항 연산자
   115→fn evalUnaryOp(operand: any, op: string): any {
   116→  if op == "-" {
   117→    return 0 - operand
   118→  } else if op == "!" {
   119→    return not operand
   120→  } else {
   121→    return null
   122→  }
   123→}
   124→
   125→# ================================================================
   126→# Part 2.5: Return 신호 처리 (조기 종료)
   127→# ================================================================
   128→
   129→# Return 신호 생성
   130→fn createReturnSignal(value: any): map {
   131→  return {
   132→    "__return": true,
   133→    "value": value
   134→  }
   135→}
   136→
   137→# Return 신호 확인
   138→fn isReturnSignal(value: any): bool {
   139→  if value is map {
   140→    return value["__return"] == true
   141→  }
   142→  return false
   143→}
   144→
   145→# Return 신호에서 값 추출
   146→fn extractReturnValue(signal: map): any {
   147→  return signal["value"]
   148→}
   149→
   150→# ================================================================
   151→# Part 3: 제어 흐름
   152→# ================================================================
   153→
   154→# If 문 (return 신호 전파)
   155→fn evalIf(condition: any, thenBranch: map, elseBranch: map, env: map): any {
   156→  if condition {
   157→    # then 브랜치 result가 return 신호일 수 있음 → 그대로 전파
   158→    return evalNode(thenBranch, env)
   159→  } else if elseBranch != null {
   160→    # else 브랜치 result가 return 신호일 수 있음 → 그대로 전파
   161→    return evalNode(elseBranch, env)
   162→  } else {
   163→    return null
   164→  }
   165→}
   166→
   167→# While 루프 (return 신호 전파)
   168→fn evalWhile(condition_node: map, body: map, env: map): any {
   169→  let result = null
   170→
   171→  while true {
   172→    let cond_value = evalNode(condition_node, env)
   173→    if not cond_value {
   174→      break
   175→    }
   176→    result = evalNode(body, env)
   177→    # Return 신호 감지 → 즉시 루프 탈출
   178→    if isReturnSignal(result) {
   179→      return result
   180→    }
   181→  }
   182→
   183→  return result
   184→}
   185→
   186→# For 루프 (return 신호 전파)
   187→fn evalFor(variable: string, start_node: map, end_node: map, body: map, env: map): any {
   188→  let start = evalNode(start_node, env)
   189→  let end = evalNode(end_node, env)
   190→  let result = null
   191→
   192→  let i = start
   193→  while i < end {
   194→    setVariable(variable, i, env)
   195→    result = evalNode(body, env)
   196→    # Return 신호 감지 → 즉시 루프 탈출
   197→    if isReturnSignal(result) {
   198→      return result
   199→    }
   200→    i = i + 1
   201→  }
   202→
   203→  return result
   204→}
   205→
   206→# For-in 루프 (return 신호 전파)
   207→fn evalForIn(variable: string, iterable_node: map, body: map, env: map): any {
   208→  let iterable = evalNode(iterable_node, env)
   209→  let result = null
   210→
   211→  # 배열 순회
   212→  if iterable is [any] {
   213→    let i = 0
   214→    while i < len(iterable) {
   215→      setVariable(variable, iterable[i], env)
   216→      result = evalNode(body, env)
   217→      # Return 신호 감지 → 즉시 루프 탈출
   218→      if isReturnSignal(result) {
   219→        return result
   220→      }
   221→      i = i + 1
   222→    }
   223→  }
   224→  # 맵(딕셔너리) 순회
   225→  else if iterable is map {
   226→    # 맵의 경우, keys를 추출하여 순회
   227→    # 주의: FreeLang에서 map iteration이 제한적이므로, 여기서는 value만 순회
   228→    let i = 0
   229→    let keys = []  # TODO: mapKeys 함수 사용 필요
   230→    while i < len(keys) {
   231→      setVariable(variable, iterable[keys[i]], env)
   232→      result = evalNode(body, env)
   233→      if isReturnSignal(result) {
   234→        return result
   235→      }
   236→      i = i + 1
   237→    }
   238→  }
   239→
   240→  return result
   241→}
   242→
   243→# 블록 (return 신호 전파)
   244→fn evalBlock(statements: [map], env: map): any {
   245→  let result = null
   246→  let i = 0
   247→
   248→  while i < len(statements) {
   249→    result = evalNode(statements[i], env)
   250→    # Return 신호 감지 → 즉시 루프 탈출
   251→    if isReturnSignal(result) {
   252→      return result
   253→    }
   254→    i = i + 1
   255→  }
   256→
   257→  return result
   258→}
   259→
   260→# ================================================================
   261→# Part 4: 함수 호출
   262→# ================================================================
   263→
   264→# 내장 함수 (표준 라이브러리)
   265→fn isBuiltinFunction(name: string): bool {
   266→  let builtins = ["print", "println", "len", "toString", "toNumber"]
   267→  let i = 0
   268→  while i < len(builtins) {
   269→    if builtins[i] == name {
   270→      return true
   271→    }
   272→    i = i + 1
   273→  }
   274→  return false
   275→}
   276→
   277→# 내장 함수 호출
   278→fn callBuiltin(name: string, args: [any]): any {
   279→  if name == "print" {
   280→    # TODO: 실제 출력 구현
   281→    return null
   282→  } else if name == "println" {
   283→    # TODO: 실제 출력 구현
   284→    return null
   285→  } else if name == "len" {
   286→    return len(args[0])
   287→  } else if name == "toString" {
   288→    return toString(args[0])
   289→  } else if name == "toNumber" {
   290→    return toNumber(args[0])
   291→  } else {
   292→    return null
   293→  }
   294→}
   295→
   296→# 함수 호출 평가 (return 신호 처리)
   297→fn evalFunctionCall(name: string, arg_nodes: [map], env: map): any {
   298→  # 내장 함수
   299→  if isBuiltinFunction(name) {
   300→    let args = []
   301→    let i = 0
   302→    while i < len(arg_nodes) {
   303→      args[i] = evalNode(arg_nodes[i], env)
   304→      i = i + 1
   305→    }
   306→    return callBuiltin(name, args)
   307→  }
   308→
   309→  # 사용자 정의 함수
   310→  let funcs = env["functions"]
   311→  let func = funcs[name]
   312→
   313→  if func == null {
   314→    return null  # 함수 정의 안 됨
   315→  }
   316→
   317→  # 인자 평가
   318→  let args = []
   319→  let i = 0
   320→  while i < len(arg_nodes) {
   321→    args[i] = evalNode(arg_nodes[i], env)
   322→    i = i + 1
   323→  }
   324→
   325→  # 새 환경 생성
   326→  let callEnv = {
   327→    "variables": {},
   328→    "functions": funcs,
   329→    "parent": env
   330→  }
   331→
   332→  # 매개변수 바인딩
   333→  let params = func["params"]
   334→  i = 0
   335→  while i < len(params) {
   336→    setVariable(params[i], args[i], callEnv)
   337→    i = i + 1
   338→  }
   339→
   340→  # 함수 본문 실행
   341→  let result = evalNode(func["body"], callEnv)
   342→
   343→  # Return 신호 처리: 신호를 풀고 실제 값만 반환
   344→  if isReturnSignal(result) {
   345→    return extractReturnValue(result)
   346→  }
   347→
   348→  return result
   349→}
   350→
   351→# ================================================================
   352→# Part 5: 메인 평가 함수 (AST 순회)
   353→# ================================================================
   354→
   355→fn evalNode(node: map, env: map): any {
   356→  if node == null {
   357→    return null
   358→  }
   359→  
   360→  let nodeType = node["type"]
   361→  
   362→  # 리터럴
   363→  if nodeType == "number" {
   364→    return node["value"]
   365→  } else if nodeType == "string" {
   366→    return node["value"]
   367→  } else if nodeType == "identifier" {
   368→    return getVariable(node["name"], env)
   369→  } else if nodeType == "boolean" {
   370→    return node["value"]
   371→  }
   372→  
   373→  # 이진 연산
   374→  else if nodeType == "binaryOp" {
   375→    let left = evalNode(node["left"], env)
   376→    let right = evalNode(node["right"], env)
   377→    return evalBinaryOp(left, right, node["operator"])
   378→  }
   379→  
   380→  # 단항 연산
   381→  else if nodeType == "unaryOp" {
   382→    let operand = evalNode(node["operand"], env)
   383→    return evalUnaryOp(operand, node["operator"])
   384→  }
   385→  
   386→  # 함수 호출
   387→  else if nodeType == "functionCall" {
   388→    return evalFunctionCall(node["name"], node["args"], env)
   389→  }
   390→  
   391→  # 변수 할당
   392→  else if nodeType == "assignment" {
   393→    let value = evalNode(node["value"], env)
   394→    return setVariable(node["variable"], value, env)
   395→  }
   396→  
   397→  # If 문
   398→  else if nodeType == "if" {
   399→    let cond = evalNode(node["condition"], env)
   400→    return evalIf(cond, node["thenBranch"], node["elseBranch"], env)
   401→  }
   402→  
   403→  # While 루프
   404→  else if nodeType == "while" {
   405→    return evalWhile(node["condition"], node["body"], env)
   406→  }
   407→  
   408→  # For 루프
   409→  else if nodeType == "for" {
   410→    return evalFor(node["variable"], node["start"], node["end"], node["body"], env)
   411→  }
   412→
   413→  # For-in 루프
   414→  else if nodeType == "forInStatement" {
   415→    return evalForIn(node["variable"], node["iterable"], node["body"], env)
   416→  }
   417→  
   418→  # 블록
   419→  else if nodeType == "block" {
   420→    return evalBlock(node["statements"], env)
   421→  }
   422→  
   423→  # 배열 리터럴
   424→  else if nodeType == "arrayLiteral" {
   425→    let elements = node["elements"]
   426→    let result = []
   427→    let i = 0
   428→    while i < len(elements) {
   429→      result[i] = evalNode(elements[i], env)
   430→      i = i + 1
   431→    }
   432→    return result
   433→  }
   434→
   435→  # 딕셔너리 리터럴
   436→  else if nodeType == "dictLiteral" {
   437→    let result: map = {}
   438→    let pairs = node["pairs"]
   439→    let i = 0
   440→    while i < len(pairs) {
   441→      let pair = pairs[i]
   442→      let key = pair["key"]
   443→      let value = evalNode(pair["value"], env)
   444→      result[key] = value
   445→      i = i + 1
   446→    }
   447→    return result
   448→  }
   449→  
   450→  # 배열 접근
   451→  else if nodeType == "arrayAccess" {
   452→    let array = evalNode(node["array"], env)
   453→    let index = evalNode(node["index"], env)
   454→    return array[index]
   455→  }
   456→
   457→  # 멤버 접근
   458→  else if nodeType == "memberAccess" {
   459→    let object = evalNode(node["object"], env)
   460→    let property = node["property"]
   461→    if object is map {
   462→      return object[property]
   463→    }
   464→    return null
   465→  }
   466→
   467→  # 멤버 할당 (obj.prop = value)
   468→  else if nodeType == "memberAssignment" {
   469→    let object = evalNode(node["object"], env)
   470→    let value = evalNode(node["value"], env)
   471→    let property = node["property"]
   472→    if object is map {
   473→      object[property] = value
   474→      return value
   475→    }
   476→    return null
   477→  }
   478→
   479→  # 함수 정의
   480→  else if nodeType == "functionDef" {
   481→    let params = node["params"]
   482→    let body = node["body"]
   483→    defineFunction(node["name"], params, body, env)
   484→    return null
   485→  }
   486→
   487→  # Struct 정의
   488→  else if nodeType == "structDefinition" {
   489→    let name = node["name"]
   490→    let fields = node["fields"]
   491→    defineStruct(name, fields, env)
   492→    return null
   493→  }
   494→  
   495→  # 반환 (return 신호 생성)
   496→  else if nodeType == "return" {
   497→    let returnValue = evalNode(node["value"], env)
   498→    return createReturnSignal(returnValue)
   499→  }
   500→  
   501→  else {
   502→    return null
   503→  }
   504→}
   505→
   506→# ================================================================
   507→# Part 6: 메인 진입점
   508→# ================================================================
   509→
   510→fn main() {
   511→  let env = createEnv()
   512→  
   513→  # 예제 코드 실행
   514→  # TODO: 파일에서 읽거나 REPL로 처리
   515→  
   516→  return null
   517→}
   518→
